/* ============================================================
   AK 终端 —— ak-ui 设计语言皮肤（强度：terminal）
   令牌层内联自 @yunyoujun/ak-ui@1.0.0 dist/tokens.css，
   使皮肤自包含：导出 / 分享后不依赖 npm 包或全局样式。
   布局能力 manifest.layout:"terminal" 由 App.vue 消费
   （隐藏侧栏、落地命令面板主页、<html data-lm-terminal> 钩子）。
   ============================================================ */

/* ---- 1. ak-ui 语义令牌层（原样内联，勿改语义） ---- */
:root{
--ak-color-white:white;--ak-color-black:black;--ak-color-low:#9c9c9c;--ak-color-basic:#d8dd5a;
--ak-color-primary:#4aabea;--ak-color-secondary:#cfc2d1;--ak-color-advanced:#f1c644;
--ak-color-accent:#f6540e;--ak-color-blue:#2bf;--ak-color-yellow:#ffd802;
--ak-color-dark-blue:#0075a8;--ak-color-light-blue:#3ff7ff;--ak-color-gray:#313131;--ak-color-dark:#222;
--ak-surface-canvas:#111315;--ak-surface-panel:rgba(253,253,251,.9);--ak-surface-muted:rgba(235,236,235,.9);
--ak-surface-raised:rgba(66,66,66,.92);--ak-surface-inverse:#17191b;
--ak-text-primary:#f8f8f5;--ak-text-secondary:rgba(248,248,245,.68);--ak-text-inverse:#1b1d1f;
--ak-signal-info:var(--ak-color-primary);--ak-signal-action:var(--ak-color-advanced);
--ak-signal-accent:var(--ak-color-accent);--ak-signal-success:#46c47c;--ak-signal-danger:#e33b3b;
--ak-signal-disabled:var(--ak-color-low);
--ak-font-sans:"Roboto","SarasaGothicSC-Regular","Microsoft YaHei",system-ui,sans-serif;
--ak-font-serif:"Noto Serif SC","SarasaGothicSC-Regular",serif;
--ak-font-mono:ui-monospace,"Cascadia Mono",Consolas,"SarasaGothicSC-Regular",monospace;
--ak-font-command:var(--ak-font-sans);
--ak-type-display-size:clamp(2rem,4vw,3.25rem);--ak-type-title-size:1.75rem;--ak-type-label-size:.6875rem;
--ak-type-data-size:1rem;--ak-type-tight:-.02em;--ak-type-wide:.12em;
--ak-space-1:.25rem;--ak-space-2:.5rem;--ak-space-3:.75rem;--ak-space-4:1rem;--ak-space-5:1.5rem;--ak-space-6:2rem;
--ak-density-control-height:2.75rem;--ak-density-panel-padding:var(--ak-space-5);
--ak-line-hairline:1px;--ak-line-strong:4px;
--ak-cut-sm:.375rem;--ak-cut-md:.75rem;--ak-cut-lg:1.5rem;--ak-radius-subtle:2px;
--ak-shadow-panel:0 1px 0 rgba(0,0,0,.45);
--ak-shadow-signal:0 0 1rem color-mix(in srgb,var(--ak-signal-info) 62%,transparent);
--ak-depth-perspective:30em;
--ak-motion-fast:120ms;--ak-motion-base:200ms;--ak-motion-slow:420ms;
--ak-ease-standard:cubic-bezier(.2,0,0,1);--ak-ease-emphasized:cubic-bezier(.2,.8,.2,1);
--ak-focus-color:var(--ak-signal-action);--ak-focus-width:3px;--ak-focus-offset:3px;
}

/* ---- 2. 品牌映射：ak-ui 深色优先，亮面按 paper 语义反演；命令字族沿用宿主字族 ---- */
:root[data-theme="light"]{
--ak-surface-canvas:#f4f4f0;--ak-surface-panel:rgba(255,255,255,.96);--ak-surface-raised:rgba(255,255,255,.96);
--ak-surface-muted:rgba(240,240,235,.96);--ak-surface-inverse:#17191b;
--ak-text-primary:#1b1d1f;--ak-text-secondary:rgba(27,29,31,.66);--ak-text-inverse:#f8f8f5;
--ak-signal-info:#1c6fa8;--ak-signal-action:#7a5c00;--ak-signal-accent:#c0400a;
--ak-signal-success:#1f7a4d;--ak-signal-danger:#b3261e;--ak-signal-disabled:#8a8d91;
--ak-shadow-panel:0 1px 0 rgba(27,29,31,.18);
}
:root[data-theme="dark"]{
--ak-surface-canvas:#111315;--ak-surface-panel:rgba(20,23,26,.92);--ak-surface-raised:rgba(34,38,42,.92);
--ak-surface-muted:rgba(48,54,60,.92);--ak-surface-inverse:#17191b;
--ak-text-primary:#f8f8f5;--ak-text-secondary:rgba(248,248,245,.68);--ak-text-inverse:#1b1d1f;
--ak-signal-info:#4aabea;--ak-signal-action:#f1c644;--ak-signal-accent:#f6540e;
}

/* ---- 3. 项目语义几何：--lm-shape-* 被 20+ 处 scoped 样式直接引用，改这一处即全应用生效 ---- */
:root{
--lm-shape-button:var(--md-sys-shape-corner-small);
--lm-shape-card:var(--md-sys-shape-corner-medium);
--lm-shape-card-inner:var(--md-sys-shape-corner-small);
--lm-shape-dialog:var(--md-sys-shape-corner-large);
}

/* ---- 4. m3e 组件令牌（shadow DOM 唯一通道；只使用已核对的令牌名） ---- */
:root{
--m3e-focus-ring-color:var(--ak-signal-action);
--m3e-focus-ring-thickness:var(--ak-focus-width);
--m3e-focus-ring-outward-offset:var(--ak-focus-offset);
--m3e-focus-ring-inward-offset:0px;
}
:root[data-lm-terminal] m3e-button{
--m3e-button-shape-round:var(--md-sys-shape-corner-small);
--m3e-button-shape-square:var(--md-sys-shape-corner-small);
--m3e-button-label-text-tracking:var(--ak-type-wide);
--m3e-button-label-text-font-weight:700;
--m3e-button-container-elevation:0;
--m3e-button-hover-container-elevation:0;
--m3e-button-focus-container-elevation:0;
--m3e-button-pressed-container-elevation:0;
}
:root[data-lm-terminal] m3e-card{
--m3e-card-shape:var(--lm-shape-card);
--m3e-card-container-color:var(--md-sys-color-surface-container-low);
--m3e-card-outline-thickness:var(--ak-line-hairline);
--m3e-card-outline-color:var(--md-sys-color-outline-variant);
--m3e-card-container-elevation:0;
--m3e-card-hover-container-elevation:0;
--m3e-card-focus-container-elevation:0;
--m3e-card-pressed-container-elevation:0;
}
:root[data-lm-terminal] m3e-chip,
:root[data-lm-terminal] m3e-filter-chip,
:root[data-lm-terminal] m3e-assist-chip{
--m3e-chip-container-shape:var(--md-sys-shape-corner-small);
--m3e-chip-label-text-tracking:var(--ak-type-wide);
}
:root[data-lm-terminal] m3e-list-item{
--m3e-list-item-container-shape:var(--md-sys-shape-corner-extra-small);
--m3e-list-item-hover-state-layer-color:var(--md-sys-color-surface-container-high);
}
:root[data-lm-terminal] m3e-dialog{
--m3e-dialog-shape:var(--lm-shape-dialog);
--m3e-dialog-container-color:var(--md-sys-color-surface-container-high);
}
:root[data-lm-terminal] m3e-bottom-sheet{
--m3e-bottom-sheet-container-shape:var(--lm-shape-dialog);
}
:root[data-lm-terminal] m3e-linear-progress-indicator{
--m3e-linear-progress-indicator-thickness:3px;
--m3e-progress-indicator-color:var(--ak-signal-info);
}

/* ---- 5. 选项卡内部：命令规则 + 战术字距（页面标题区） ---- */
:root[data-lm-terminal] .page-head{
align-items:flex-end;
padding:0 0 var(--ak-space-3) var(--ak-space-4);
border-left:var(--ak-line-strong) solid var(--ak-signal-info);
border-bottom:var(--ak-line-hairline) solid var(--md-sys-color-outline-variant);
}
:root[data-lm-terminal] .page-head h2{
font-family:var(--ak-font-command);
font-weight:700;
letter-spacing:var(--ak-type-tight);
}
:root[data-lm-terminal] .page-head-desc{
font-family:var(--ak-font-mono);
font-size:var(--ak-type-label-size);
letter-spacing:var(--ak-type-wide);
}
:root[data-lm-terminal] .page-title,
:root[data-lm-terminal] .section-title{
font-family:var(--ak-font-command);
font-weight:700;
letter-spacing:var(--ak-type-tight);
}
:root[data-lm-terminal] .tabular-nums{
font-family:var(--ak-font-mono);
letter-spacing:var(--ak-type-tight);
}

/* ---- 6. 终端外壳：侧栏由 App.vue v-if 移除，这里兜底；标题栏去玻璃厚涂 ---- */
:root[data-lm-terminal] [data-lm-region="nav"]{
display:none;
}
:root[data-lm-terminal] [data-lm-region="titlebar"]{
border-bottom:var(--ak-line-hairline) solid var(--md-sys-color-outline-variant);
backdrop-filter:blur(10px) saturate(140%);
-webkit-backdrop-filter:blur(10px) saturate(140%);
}
:root[data-lm-terminal] [data-lm-region="titlebar"] .tb-brand-name{
font-family:var(--ak-font-mono);
font-size:11px;
letter-spacing:var(--ak-type-wide);
text-transform:uppercase;
}

/* ---- 7. 焦点可见（避开 m3e 自绘焦点环，只兜底原生控件）与动效降级 ---- */
:root[data-lm-terminal] button:focus-visible,
:root[data-lm-terminal] a:focus-visible,
:root[data-lm-terminal] input:focus-visible,
:root[data-lm-terminal] textarea:focus-visible,
:root[data-lm-terminal] [tabindex]:focus-visible{
outline:var(--ak-focus-width) solid var(--ak-focus-color);
outline-offset:var(--ak-focus-offset);
}
@media (prefers-reduced-motion:reduce){
:root[data-lm-terminal] *,
:root[data-lm-terminal] *::before,
:root[data-lm-terminal] *::after{
animation-duration:.01ms !important;
animation-iteration-count:1 !important;
transition-duration:.01ms !important;
}
}
